import * as React from "react"
import { addPropertyControls, ControlType, motion } from "framer"
import { containerStyles } from "https://framer.com/m/framer/default-utils.js@^0.45.0"
import { useMemo } from "react"
import {
    emptyStateStyle,
    stateParagraphStyle,
    stateTitleStyle,
} from "https://framer.com/m/framer/integrations-styles.js@0.2.0"

const musicRegex =
    /^https?:\/\/music\.apple\.com\/([^\/]*)\/(album|playlist)(?:\/[^\/]*)?\/([\w.-]+)(?:\?.*i=(\d+))?/

/**
 * APPLE MUSIC
 *
 * @framerIntrinsicWidth 400
 * @framerIntrinsicHeight 150
 *
 * @framerSupportedLayoutWidth fixed
 * @framerSupportedLayoutHeight fixed
 */
export default function AppleMusic({ urlType, url, style, ...props }) {
    const embedUrl = useMemo(() => {
        const [, country, type, id, songId] = url.match(musicRegex) ?? [
            null,
            "",
            "",
            "",
            "",
        ]

        if (!id) return null

        if (urlType === "song") {
            return `https://embed.music.apple.com/${country}/${type}/id${id}?i=${songId}`
        } else {
            return `https://embed.music.apple.com/${country}/${type}/id${id}`
        }
    }, [urlType, url])

    return (
        <motion.div
            style={{
                ...style,
                ...containerStyles,
            }}
            {...props}
        >
            {embedUrl ? (
                <iframe
                    src={embedUrl}
                    width="100%"
                    height="100%"
                    frameBorder="0"
                    sandbox="allow-forms allow-popups allow-same-origin allow-scripts allow-top-navigation-by-user-activation"
                    allow="autoplay *; encrypted-media *;"
                />
            ) : (
                <motion.div
                    style={{
                        ...emptyStateStyle,
                        ...style,
                    }}
                >
                    <h1 style={stateTitleStyle}>Apple Music</h1>
                    <p style={stateParagraphStyle}>
                        Set an Apple Music URL in the Properties.
                    </p>
                </motion.div>
            )}
        </motion.div>
    )
}

addPropertyControls(AppleMusic, {
    urlType: {
        type: ControlType.Enum,
        title: "URL",
        options: ["album", "song"],
        optionTitles: ["Album", "Song"],
        displaySegmentedControl: true,
        defaultValue: "song",
    },
    url: {
        type: ControlType.String,
        title: " ",
        placeholder: "https://music.apple.com/us/album/***/***",
        defaultValue:
            "https://music.apple.com/us/album/borderline/1497230760?i=1497230972",
    },
})
